#!/usr/bin/env bash
# Stream a file line by line. `read` consumes one line per iteration from the
# shell's own buffered fd — nothing is slurped into an array or variable.
set -euo pipefail

# read_lines <file> <callback>
# The callback is invoked as: callback <line_no> <line>
read_lines() {
  local file=$1 callback=$2 line line_no=0
  [[ -r $file ]] || { echo "cannot read: $file" >&2; return 1; }

  # IFS= preserves leading/trailing whitespace; -r disables backslash escapes.
  # The final `|| [[ -n $line ]]` catches a last line with no trailing newline.
  while IFS= read -r line || [[ -n $line ]]; do
    line_no=$((line_no + 1))
    "$callback" "$line_no" "$line"
  done < "$file"

  return 0
}

