"""Stream a file line by line without loading it into memory."""
from __future__ import annotations

from typing import Callable, Iterator


def iter_lines(path: str, encoding: str = "utf-8") -> Iterator[str]:
    """Yield lines one at a time; the file object buffers only a chunk."""
    with open(path, "r", encoding=encoding, newline="") as fh:
        for line in fh:  # iterating a file object is lazy
            yield line.rstrip("\r\n")


def read_lines(path: str, on_line: Callable[[str, int], None]) -> int:
    """Call on_line(line, line_number) for each line; return the line count."""
    count = 0
    for count, line in enumerate(iter_lines(path), start=1):
        on_line(line, count)
    return count


if __name__ == "__main__":
    import sys

    if len(sys.argv) != 2:
        sys.exit("usage: read_lines.py <file>")
    total = read_lines(sys.argv[1], lambda line, n: print(f"{n}\t{line}"))
