# Stream a file line by line. `read` consumes one line per iteration from the
# file descriptor; nothing is buffered beyond the current line.
set -euo pipefail

read_lines() {
  local path=$1
  local handler=${2:-}   # optional: function name called as handler "$line" "$n"
  local n=0 line

  [[ -r $path ]] || { printf 'error: cannot read %s\n' "$path" >&2; return 1; }

