describe('deepMerge', () => {
  it('overrides nested keys and keeps siblings', () => {
    const base = { a: 1, nested: { x: 1, y: 2 } };
    const override = { nested: { y: 20, z: 30 } };
    expect(deepMerge(base, override)).toEqual({ a: 1, nested: { x: 1, y: 20, z: 30 } });
  });

  it('replaces arrays instead of merging them', () => {
    expect(deepMerge({ list: [1, 2, 3] }, { list: [9] })).toEqual({ list: [9] });
  });

  it('ignores undefined overrides but honours null', () => {
    expect(deepMerge({ a: 1, b: 2 }, { a: undefined, b: null })).toEqual({ a: 1, b: null });
  });

