/**
 * Flatten a deeply nested array into a single level.
 *
 * Iterative (explicit stack) so arbitrarily deep input cannot blow the call
 * stack. Only real arrays are descended into — array-like objects, strings and
 * typed arrays are treated as leaf values.
 *
 * @param input  Arbitrarily nested array.
 * @param depth  How many levels to flatten. Default Infinity (fully flat).
 * @returns      A new flat array; the input is never mutated.
 */
export function flatten<T>(input: readonly unknown[], depth: number = Infinity): T[] {
  const out: T[] = [];
  if (depth <= 0) return input.slice() as T[];

  // Each frame is [array, index, remainingDepth].
  const stack: Array<[readonly unknown[], number, number]> = [[input, 0, depth]];

  while (stack.length > 0) {
    const frame = stack[stack.length - 1]!;
    const [arr, i, d] = frame;

    if (i >= arr.length) {
      stack.pop();
      continue;
    }
    frame[1] = i + 1;

    const value = arr[i];
    if (Array.isArray(value) && d > 1) {
      stack.push([value, 0, d - 1]);
    } else {
      out.push(value as T);
    }
  }

  return out;
}
