from typing import Any, Iterable, List


def flatten(items: Iterable[Any], depth: float = float("inf")) -> List[Any]:
    """Flatten a deeply nested list into a single level.

    Iterative (explicit stack) so arbitrarily deep input cannot hit Python's
    recursion limit. Only list/tuple containers are descended into; strings,
    dicts, sets and other iterables are treated as leaf values.

    Args:
        items: Arbitrarily nested list/tuple.
        depth: How many levels to flatten. Default inf (fully flat).

    Returns:
        A new flat list; the input is never mutated.
    """
    out: List[Any] = []
    if depth <= 0:
        return list(items)

    # Each frame is [container, index, remaining_depth].
    stack: List[list] = [[items, 0, depth]]

    while stack:
        frame = stack[-1]
        container, i, d = frame

        if i >= len(container):
            stack.pop()
            continue
        frame[1] = i + 1

        value = container[i]
        if isinstance(value, (list, tuple)) and d > 1:
            stack.append([value, 0, d - 1])
        else:
            out.append(value)

    return out
