package flatten

// Flatten collapses a deeply nested slice into a single level.
//
// It is iterative (explicit stack) so arbitrarily deep input cannot overflow
// the goroutine stack. Only []any values are descended into; strings, byte
// slices and other slice types are treated as leaf values.
//
// depth limits how many levels are flattened; use -1 for fully flat.
// The input is never mutated.
func Flatten(input []any, depth int) []any {
	out := make([]any, 0, len(input))
	if depth == 0 {
		return append(out, input...)
	}

	type frame struct {
		arr []any
		i   int
		d   int
	}
	stack := []frame{{arr: input, d: depth}}

	for len(stack) > 0 {
		top := &stack[len(stack)-1]

		if top.i >= len(top.arr) {
			stack = stack[:len(stack)-1]
			continue
		}

		value := top.arr[top.i]
		top.i++

		if nested, ok := value.([]any); ok && top.d != 1 {
			stack = append(stack, frame{arr: nested, d: top.d - 1})
			continue
		}
		out = append(out, value)
	}

	return out
}
