// Command pipeline demonstrates a three-stage channel pipeline:
//
//	stage A (produce) -> stage B (transform) -> stage C (consume)
//
// Every stage runs in its own goroutine and communicates only through
// channels. Cancellation and error propagation flow through a shared context,
// so a failure in any stage tears the whole pipeline down without leaking
// goroutines.
package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/signal"
	"strings"
	"sync"
	"syscall"
	"time"
)

// Item is the unit of work that travels through the pipeline.
type Item struct {
	ID    int
	Value string
}

// Result is what stage C emits after consuming a transformed item.
type Result struct {
	ID    int
	Value string
	Len   int
}

// produce is stage A: it generates items and closes the output channel when
// done. It respects ctx cancellation so a downstream failure stops it early.
func produce(ctx context.Context, n int) <-chan Item {
	out := make(chan Item)
	go func() {
		defer close(out)
		for i := 1; i <= n; i++ {
			item := Item{ID: i, Value: fmt.Sprintf("raw-%d", i)}
			select {
			case out <- item:
			case <-ctx.Done():
				return
			}
			// Simulate slow upstream work (I/O, API call, ...).
			select {
			case <-time.After(20 * time.Millisecond):
			case <-ctx.Done():
				return
			}
		}
	}()
	return out
}

// transform is stage B: it maps each input item to an output item. Returning
// an error cancels the pipeline via the shared cancel func.
func transform(ctx context.Context, in <-chan Item, cancel context.CancelFunc) <-chan Item {
	out := make(chan Item)
	go func() {
		defer close(out)
		for item := range in {
			// A deliberate failure on item 7 to show error propagation.
			if item.ID == 7 {
				cancel()
				return
			}
			transformed := Item{ID: item.ID, Value: strings.ToUpper(item.Value)}
			select {
			case out <- transformed:
			case <-ctx.Done():
				return
			}
		}
	}()
	return out
}

// consume is stage C: it drains the channel and collects results. It stops
// cleanly when the input channel closes or the context is cancelled.
func consume(ctx context.Context, in <-chan Item) []Result {
	var results []Result
	for {
		select {
		case item, ok := <-in:
			if !ok {
				return results
			}
			results = append(results, Result{ID: item.ID, Value: item.Value, Len: len(item.Value)})
		case <-ctx.Done():
			return results
		}
	}
}

// run wires the three stages together and waits for all of them to finish.
func run(ctx context.Context, n int) ([]Result, error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()

