// Longest Common Subsequence (LCS).
//
// Returns one longest common subsequence of a and b (a subsequence keeps order
// but need not be contiguous). Ties are broken deterministically: when skipping
// a character from a and from b are equally good, we skip from a first — the
// same rule as the TypeScript and Python versions.
//
// Time:  O(n*m)   Space: O(n*m) for the DP table (O(min(n,m)) if only the
// length is needed — see LCSLength).
package main

import "fmt"

// LCS returns one longest common subsequence of a and b.
func LCS(a, b string) string {
	ar, br := []rune(a), []rune(b) // runes, so multi-byte input is handled
	n, m := len(ar), len(br)

	// dp[i][j] = LCS length of ar[i:] and br[j:]
	dp := make([][]int, n+1)
	for i := range dp {
		dp[i] = make([]int, m+1)
	}

	for i := n - 1; i >= 0; i-- {
		for j := m - 1; j >= 0; j-- {
			if ar[i] == br[j] {
				dp[i][j] = dp[i+1][j+1] + 1
			} else if dp[i+1][j] >= dp[i][j+1] {
				dp[i][j] = dp[i+1][j]
			} else {
				dp[i][j] = dp[i][j+1]
			}
		}
	}

	// Walk the table forward, collecting matched characters.
	out := make([]rune, 0, dp[0][0])
	i, j := 0, 0
	for i < n && j < m {
		switch {
		case ar[i] == br[j]:
			out = append(out, ar[i])
			i++
			j++
		case dp[i+1][j] >= dp[i][j+1]:
			i++
		default:
			j++
		}
	}
	return string(out)
}

// LCSLength returns only the length, using O(min(n, m)) extra space.
func LCSLength(a, b string) int {
	ar, br := []rune(a), []rune(b)
	if len(br) > len(ar) {
		ar, br = br, ar // br is the shorter one
	}
	m := len(br)
	prev := make([]int, m+1)
	cur := make([]int, m+1)

	for i := 1; i <= len(ar); i++ {
		for j := 1; j <= m; j++ {
			if ar[i-1] == br[j-1] {
				cur[j] = prev[j-1] + 1
			} else if prev[j] >= cur[j-1] {
				cur[j] = prev[j]
			} else {
				cur[j] = cur[j-1]
			}
		}
		prev, cur = cur, prev
	}
	return prev[m]
}

func main() {
	cases := [][2]string{
		{"ABCBDAB", "BDCABA"},
		{"AGGTAB", "GXTXAYB"},
		{"", "abc"},
		{"abc", "abc"},
		{"abc", "def"},
	}
	for _, c := range cases {
		s := LCS(c[0], c[1])
		fmt.Printf("lcs(%q, %q) = %q (len %d, check %d)\n", c[0], c[1], s, len([]rune(s)), LCSLength(c[0], c[1]))
	}
}
