"""Floyd's cycle detection ("tortoise and hare") for singly linked lists.

Time:  O(n)  -- the hare advances at most n steps before reaching the end or
                meeting the tortoise inside the cycle.
Space: O(1)  -- two pointers, no visited set.

The second phase (finding the cycle entry) is the part people forget: after
the meeting point, reset one pointer to the head and advance both one step at
a time; they meet exactly at the first node of the cycle.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Generic, Optional, Sequence, TypeVar

T = TypeVar("T")


@dataclass
class ListNode(Generic[T]):
    value: T
    next: Optional["ListNode[T]"] = None


def build_list(values: Sequence[T], cycle_at: int = -1) -> Optional[ListNode[T]]:
    """Build a list from values; if cycle_at >= 0, the tail links back to that index."""
    if not values:
        return None
    nodes = [ListNode(v) for v in values]
    for current, following in zip(nodes, nodes[1:]):
        current.next = following
    if 0 <= cycle_at < len(nodes):
        nodes[-1].next = nodes[cycle_at]
    return nodes[0]


def has_cycle(head: Optional[ListNode[T]]) -> bool:
    """True if the list contains a cycle."""
    slow = fast = head
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False


def find_cycle_start(head: Optional[ListNode[T]]) -> Optional[ListNode[T]]:
    """Return the node where the cycle begins, or None if there is no cycle."""
    slow = fast = head

    # Phase 1: detect the meeting point.
    while fast is not None and fast.next is not None:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            break
    else:
        return None  # loop ran to completion: no cycle
    if fast is None or fast.next is None:
        return None

    # Phase 2: head and meeting point are both `k` steps from the entry,
    # where k = distance from head to the cycle entry.
    slow = head
    while slow is not fast:
        slow = slow.next
        fast = fast.next
    return slow


def cycle_length(head: Optional[ListNode[T]]) -> int:
    """Length of the cycle, or 0 if there is none."""
    start = find_cycle_start(head)
    if start is None:
        return 0
    length = 1
    node = start.next
    while node is not start:
        node = node.next
        length += 1
    return length


