    cyclic = build_list([1, 2, 3, 4, 5], cycle_at=2)  # tail -> node with value 3

    print("acyclic: has_cycle =", has_cycle(acyclic))
    print("cyclic:  has_cycle =", has_cycle(cyclic))
    start = find_cycle_start(cyclic)
    print("cyclic:  cycle starts at", start.value if start else None)
    print("cyclic:  cycle length =", cycle_length(cyclic))
