// Package floyd implements Floyd's cycle detection ("tortoise and hare") for
// singly linked lists.
//
// Time:  O(n)  — the hare advances at most n steps before reaching the end or
//                meeting the tortoise inside the cycle.
// Space: O(1)  — two pointers, no visited set.
//
// The second phase (finding the cycle entry) is the part people forget: after
// the meeting point, reset one pointer to the head and advance both one step
// at a time; they meet exactly at the first node of the cycle.
package floyd

// Node is a singly linked list node.
type Node[T any] struct {
	Value T
	Next  *Node[T]
}

// BuildList builds a list from values. If cycleAt >= 0, the tail links back to
// that index, creating a cycle.
func BuildList[T any](values []T, cycleAt int) *Node[T] {
	if len(values) == 0 {
		return nil
	}
	nodes := make([]*Node[T], len(values))
	for i, v := range values {
		nodes[i] = &Node[T]{Value: v}
	}
	for i := 0; i < len(nodes)-1; i++ {
		nodes[i].Next = nodes[i+1]
	}
	if cycleAt >= 0 && cycleAt < len(nodes) {
		nodes[len(nodes)-1].Next = nodes[cycleAt]
	}
	return nodes[0]
}

// HasCycle reports whether the list contains a cycle.
func HasCycle[T any](head *Node[T]) bool {
	slow, fast := head, head
	for fast != nil && fast.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
		if slow == fast {
			return true
		}
	}
	return false
}

// FindCycleStart returns the node where the cycle begins, or nil if there is
// no cycle.
func FindCycleStart[T any](head *Node[T]) *Node[T] {
	slow, fast := head, head

	// Phase 1: detect the meeting point.
	for fast != nil && fast.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
		if slow == fast {
			break
		}
	}
	if fast == nil || fast.Next == nil {
		return nil // no cycle
	}

	// Phase 2: head and meeting point are both `k` steps from the entry,
	// where k = distance from head to the cycle entry.
	slow = head
	for slow != fast {
		slow = slow.Next
		fast = fast.Next
	}
	return slow
}

// CycleLength returns the length of the cycle, or 0 if there is none.
func CycleLength[T any](head *Node[T]) int {
	start := FindCycleStart(head)
	if start == nil {
		return 0
	}
	length := 1
	for node := start.Next; node != start; node = node.Next {
		length++
	}
	return length
}
